package cn.courselens;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
public class AiAttachmentTest {
 @Test public void documentsBecomeCloudTextAndRemainSeparateFromChatDraft()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiAttachment txt=AiAttachment.decode(c,"笔记.txt","实验数据".getBytes(StandardCharsets.UTF_8)).get(0);assertEquals("实验数据",txt.upload("unused",new DeepSeekClient.Call()).getString("text"));assertNull(txt.image);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("word/document.xml"));zip.write("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:p><w:r><w:t>报告正文</w:t></w:r></w:p></w:document>".getBytes(StandardCharsets.UTF_8));zip.closeEntry();}AiAttachment doc=AiAttachment.decode(c,"报告.docx",bytes.toByteArray()).get(0);assertTrue(doc.text.contains("报告正文"));}
 @Test public void filesAndDecodedTextAreBoundedAndBinaryIsRejected()throws Exception{try{AiAttachment.bounded(new ByteArrayInputStream(new byte[33]),32);fail();}catch(IOException expected){}try{AiAttachment.decode(RuntimeEnvironment.getApplication(),"binary.dat",new byte[]{0,1,2});fail();}catch(IOException expected){}try{AiAttachment.decode(RuntimeEnvironment.getApplication(),"large.txt","a".repeat(64001).getBytes(StandardCharsets.UTF_8));fail();}catch(IOException expected){}}
 @Test public void photographsRemainImagesWithoutOcr()throws Exception{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);ByteArrayOutputStream png=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,png);bitmap.recycle();AiAttachment image=AiAttachment.decode(RuntimeEnvironment.getApplication(),"照片.png",png.toByteArray()).get(0);assertEquals("image/png",image.mime);assertNotNull(image.image);assertNull(image.text);}
}
